import{_ as i,c as o,o as a,j as s,Y as r,t as n}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"git-mergetool--lib | x-cmd man (git man1) | Common Git merge tool shell scriptlets","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-mergetool--lib - Common Git merge tool shell scriptlets","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-mergetool--lib | x-cmd man (git man1) | Common Git merge tool shell scriptlets"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-mergetool--lib - Common Git merge tool shell scriptlets"}]]},"headers":[],"params":{"isMan":true,"man":"git-mergetool--lib","category":"git man1","desc":"Common Git merge tool shell scriptlets"},"relativePath":"git/man1/git-mergetool--lib.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-mergetool--lib.md"},m={class:"visually-hidden"};function h(t,e,p,g,d,c){return a(),o("div",null,[s("h1",m,n(t.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-mergetool--lib - Common Git merge tool shell scriptlets</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOOL_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">diff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">merge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exec-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)/git-mergetool--lib&quot;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This is not a command the end user would want to run. Ever. This documentation is meant for people who are studying the Porcelain-ish scripts and/or are writing new ones.</p><p>The <em>git-mergetool--lib</em> scriptlet is designed to be sourced (using <strong>.</strong>) by other shell scripts to set up functions for working with Git merge tools.</p><p>Before sourcing <em>git-mergetool--lib</em>, your script must set <strong>TOOL_MODE</strong> to define the operation mode for the functions listed below. <em>diff</em> and <em>merge</em> are valid values.</p><h2 id="functions" tabindex="-1">FUNCTIONS <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;FUNCTIONS&quot;">​</a></h2><p>get_merge_tool</p><blockquote><p>returns a merge tool. the return code is 1 if we returned a guessed merge tool, else 0. <em>$GIT_MERGETOOL_GUI</em> may be set to <em>true</em> to search for the appropriate guitool.</p></blockquote><p>get_merge_tool_cmd</p><blockquote><p>returns the custom command for a merge tool.</p></blockquote><p>get_merge_tool_path</p><blockquote><p>returns the custom path for a merge tool.</p></blockquote><p>initialize_merge_tool</p><blockquote><p>bring merge tool specific functions into scope so they can be used or overridden.</p></blockquote><p>run_merge_tool</p><blockquote><p>launches a merge tool given the tool name and a true/false flag to indicate whether a merge base is present. <em>$MERGED</em>, <em>$LOCAL</em>, <em>$REMOTE</em>, and <em>$BASE</em> must be defined for use by the merge tool.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',21))])}const b=i(l,[["render",h]]);export{k as __pageData,b as default};
